 * Parses election text into a structured election, or throws a ParseError
 * describing the first problem found (with a line number when one applies).
 */

export class ParseError extends Error {
  constructor(message, line) {
    super(line === undefined ? `error: ${message}` : `error: line ${line}: ${message}`)
    this.line = line
  }
}

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^(0|[1-9][0-9]*)$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null // array of names, in declared order
  let candidateSet = null // Set of names
  let candidatesDeclared = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError('expected candidates <name>...', lineNumber)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNumber)
        }
        seen.add(name)
      }
      candidates = names
      candidateSet = seen
      candidatesDeclared = true
    } else if (word === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr) || countStr === '0') {
        throw new ParseError('count must be a positive integer', lineNumber)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${word}`, lineNumber)
    }
  }

  if (!candidatesDeclared) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

