{"file_path":"./src/count.js","content":"/**
 * Runs the instant-runoff count over a parsed election and returns the full
 * round-by-round record: how each round tallied, who (if anyone) was
 * eliminated, and who (if anyone) eventually won.
 */

export function countElection(election) {
  const { candidates, ballots } = election

  let continuing = new Set(candidates)
  // history[name] = array of vote counts, one per round the candidate was
  // continuing for, in round order starting at round 1.
  const history = {}
  for (const name of candidates) history[name] = []

  const rounds = []
  let winner = null
  let roundNumber = 0

  for (;;) {
    roundNumber++
    const votes = {}
    for (const name of continuing) votes[name] = 0
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((n) => continuing.has(n))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes[choice] += ballot.count
      }
    }

    for (const name of continuing) history[name].push(votes[name])

    const activeTotal = Object.values(votes).reduce((a, b) => a + b, 0)

    const order = [...continuing].sort((a, b) => {
      if (votes[a] !== votes[b]) return votes[b] - votes[a]
      return a < b ? -1 : a > b ? 1 : 0
    })

    const round = { number: roundNumber, votes, order, exhausted, eliminated: null }
    rounds.push(round)

    if (activeTotal === 0) {
      winner = null
      break
    }

    const top = order[0]
    if (votes[top] * 2 > activeTotal) {
      winner = top
      break
    }

    let min = Infinity
    for (const name of continuing) if (votes[name] < min) min = votes[name]
    const tied = [...continuing].filter((name) => votes[name] === min)

    const eliminated = tied.length === 1 ? tied[0] : resolveTie(tied, history, roundNumber)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function resolveTie(tied, history, currentRound) {
  let set = tied.slice()
  while (set.length > 1) {
    let narrowed = false
    for (let r = 1; r <= currentRound; r++) {
      const vals = set.map((c) => history[c][r - 1])
      const min = Math.min(...vals)
      if (!vals.every((v) => v === min)) {
        set = set.filter((c) => history[c][r - 1] === min)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }
  if (set.length === 1) return set[0]
  return set.reduce((a, b) => (a > b ? a : b))
}
"}

