/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { countElection } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const text = Buffer.concat(chunks.map((c) => (typeof c === 'string' ? Buffer.from(c) : c))).toString('utf8')

  let election
  try {
    election = parseElection(text)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  const { rounds, winner } = countElection(election)

  const out = []
  if (mode === 'rounds') {
    for (const round of rounds) {
      const parts = round.order.map((name) => `${name}=${round.votes[name]}`)
      parts.push(`exhausted=${round.exhausted}`)
      out.push(`round ${round.number}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    }
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

